"""
再帰深度制限回避 (Recursion Limit & Generator Bootstrap)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
Python のデフォルト再帰上限 (1000) による RecursionError や、
PyPy / CPython での C-stack overflow を回避するためのスニペット。

【方法1: setrecursionlimit】
- sys.setrecursionlimit(2000000) を設定する (通常はこれで十分)

【方法2: bootstrap デコレータ】
- ジェネレータ (yield) を使って再帰呼び出しをループ＋ヒープスタックに変換。
- 10^6 以上の深さの木走査やDFSでも絶対にスタックオーバーフローしない。
- 関数内で再帰呼び出しする際 `yield func(...)` と記述。
"""

import sys
from types import GeneratorType

# https://github.com/ddfkit/acsampl/blob/main/recursion_mod.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
sys.setrecursionlimit(2000000)

# https://github.com/ddfkit/acsampl/blob/main/recursion_mod.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def bootstrap(f,st=[]):
    def wrap(*args,**kwargs):
        if st:return f(*args,**kwargs)
        to=f(*args,**kwargs)
        while True:
            if type(to) is GeneratorType:st.append(to);to=next(to)
            else:
                st.pop()
                if not st:break
                to=st[-1].send(to)
        return to
    return wrap

if __name__ == "__main__":
    @bootstrap
    def dfs(n):
        if n <= 0: yield 0
        else: yield (yield dfs(n - 1)) + 1

    assert dfs(5000) == 5000
    print("recursion_mod.py: tests passed!")